def nth_magical_number(n: int, a: int, b: int) -> int:
    MOD = 10**9 + 7
    lcm = a * b // math.gcd(a, b)

    def count_up_to(x: int) -> int:
        # inclusion exclusion over multiples of a, of b, and of both
        return x // a + x // b - x // lcm

    lo, hi = min(a, b), n * min(a, b)
    while lo < hi:
        mid = (lo + hi) // 2
        if count_up_to(mid) >= n:
            hi = mid
        else:
            lo = mid + 1
    return lo % MOD

def longest_subsequence_repeated_k(s: str, k: int) -> str:
    counts = Counter(s)
    letters = sorted(c for c in counts if counts[c] >= k)   # only these can appear

    def repeated(seq: str) -> bool:
        # Is seq * k a subsequence of s?  Walk s once with a shared iterator.
        it = iter(s)
        return all(ch in it for ch in seq * k)

    best = ""
    queue = deque([""])
    while queue:
        cur = queue.popleft()
        for c in letters:
            cand = cur + c
            if repeated(cand):
                queue.append(cand)
                if len(cand) >= len(best):     # later at same length = lexicographically larger
                    best = cand
    return best

def gcd_sum(nums: List[int]) -> int:
    prefix_gcd = []
    running_max = 0
    for x in nums:
        running_max = max(running_max, x)
        prefix_gcd.append(math.gcd(x, running_max))
    prefix_gcd.sort()
    n = len(prefix_gcd)
    # pair the i-th smallest with the i-th largest; the odd middle is left out
    return sum(math.gcd(prefix_gcd[i], prefix_gcd[n - 1 - i]) for i in range(n // 2))

