def validate_binary_tree_nodes(n: int, leftChild: List[int], rightChild: List[int]) -> bool:
    indegree = [0] * n
    for child in leftChild + rightChild:
        if child != -1:
            indegree[child] += 1
            if indegree[child] > 1:        # a node with two parents
                return False
    roots = [i for i in range(n) if indegree[i] == 0]
    if len(roots) != 1:                    # no root, or a forest
        return False
    # Every node reachable from the single root?  (rules out a detached cycle)
    seen = 0
    stack = [roots[0]]
    while stack:
        node = stack.pop()
        seen += 1
        for child in (leftChild[node], rightChild[node]):
            if child != -1:
                stack.append(child)
    return seen == n

