def find_distance(root: Optional[TreeNode], p: int, q: int) -> int:
    parent = {root.val: None}
    depth = {root.val: 0}
    queue = deque([root])
    while queue:
        node = queue.popleft()
        for child in (node.left, node.right):
            if child is not None:
                parent[child.val] = node.val
                depth[child.val] = depth[node.val] + 1
                queue.append(child)

    # climb the deeper node first, then both together, counting edges walked
    dist = 0
    while depth[p] > depth[q]:
        p = parent[p]; dist += 1
    while depth[q] > depth[p]:
        q = parent[q]; dist += 1
    while p != q:
        p = parent[p]; q = parent[q]; dist += 2
    return dist

