def number_of_special_chars(word: str) -> int:
    last_lower = [-1] * 26
    first_upper = [-1] * 26
    for i, ch in enumerate(word):
        if ch.islower():
            last_lower[ord(ch) - ord("a")] = i
        else:
            c = ord(ch) - ord("A")
            if first_upper[c] == -1:
                first_upper[c] = i
    # special: both cases present, and the last lowercase comes before the first uppercase
    return sum(1 for c in range(26) if last_lower[c] != -1 and first_upper[c] != -1 and last_lower[c] < first_upper[c])

