def range_sum(nums: List[int], n: int, left: int, right: int) -> int:
    MOD = 10**9 + 7
    pre = [0] * (n + 1)                 # prefix sums of nums
    for i, x in enumerate(nums):
        pre[i + 1] = pre[i] + x
    pre_pre = [0] * (n + 2)             # prefix sums of pre
    for i in range(n + 1):
        pre_pre[i + 1] = pre_pre[i] + pre[i]

    def count_and_total(v: int):
        # number of subarrays with sum <= v, and the sum of those subarray sums
        count = total = 0
        i = 0
        for j in range(n):
            while pre[j + 1] - pre[i] > v:
                i += 1
            width = j - i + 1
            count += width
            total += width * pre[j + 1] - (pre_pre[j + 1] - pre_pre[i])
        return count, total

    def sum_of_smallest(k: int) -> int:
        if k == 0:
            return 0
        lo, hi = 1, pre[n]
        while lo < hi:                  # smallest v with at least k subarray sums <= v
            mid = (lo + hi) // 2
            if count_and_total(mid)[0] >= k:
                hi = mid
            else:
                lo = mid + 1
        count, total = count_and_total(lo)
        return total - (count - k) * lo # drop the surplus copies of the threshold value

    return (sum_of_smallest(right) - sum_of_smallest(left - 1)) % MOD

