class CBTInserter:
    def __init__(self, root: Optional[TreeNode]):
        self.root = root
        self.nodes = []                 # every node in level order
        queue = deque([root])
        while queue:
            node = queue.popleft()
            self.nodes.append(node)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        self.free = 0                   # index of the first node with an empty child slot
        while self.nodes[self.free].right is not None:
            self.free += 1

    def insert(self, val: int) -> int:
        node = TreeNode(val)
        parent = self.nodes[self.free]
        if parent.left is None:
            parent.left = node
        else:
            parent.right = node
            self.free += 1              # this parent is now full
        self.nodes.append(node)
        return parent.val

    def get_root(self) -> Optional[TreeNode]:
        return self.root

