def smallest_beautiful_string(s: str, k: int) -> str:
    code = [ord(ch) - 97 for ch in s]
    n = len(code)

    def clashes(pos: int, c: int) -> bool:
        # c at pos would form a palindrome with its previous one or two letters
        return (pos >= 1 and code[pos - 1] == c) or (pos >= 2 and code[pos - 2] == c)

    for i in range(n - 1, -1, -1):
        c = code[i] + 1
        while c < k and clashes(i, c):
            c += 1
        if c >= k:
            continue                    # position i cannot be raised; try further left
        code[i] = c
        for j in range(i + 1, n):      # refill the suffix with the smallest valid letters
            c = 0
            while clashes(j, c):
                c += 1
            code[j] = c
        return "".join(chr(97 + x) for x in code)
    return ""

