def check_valid_grid(grid: list[list[int]]) -> bool:
    n = len(grid)
    if grid[0][0] != 0:
        return False
    where = [None] * (n * n)   # step number -> (row, col)
    for r in range(n):
        for c in range(n):
            where[grid[r][c]] = (r, c)
    for step in range(1, n * n):
        if where[step] is None or where[step - 1] is None:
            return False
        r1, c1 = where[step - 1]
