def sequence_reconstruction(nums: list[int], sequences: list[list[int]]) -> bool:
    n = len(nums)
    graph = [[] for _ in range(n + 1)]
    indegree = [0] * (n + 1)
    for seq in sequences:
        for a, b in zip(seq, seq[1:]):
            graph[a].append(b)
            indegree[b] += 1

    ready = [v for v in range(1, n + 1) if indegree[v] == 0]
    order = []
    while ready:
        if len(ready) > 1:        # two candidates: the order is not unique
            return False
        v = ready.pop()
        order.append(v)
        for w in graph[v]:
            indegree[w] -= 1
            if indegree[w] == 0:
                ready.append(w)
    return order == nums

