def number_of_good_paths(vals: list[int], edges: list[list[int]]) -> int:
    n = len(vals)
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:      # path compression
            parent[x], x = root, parent[x]
        return root

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    by_value = defaultdict(list)
    for node, v in enumerate(vals):
        by_value[v].append(node)

    total = 0
    for v in sorted(by_value):
        group = by_value[v]
        for node in group:
            for nb in adj[node]:
                if vals[nb] <= v:          # already activated or same value
                    union(node, nb)
        members = Counter(find(node) for node in group)
        for c in members.values():
            total += c * (c + 1) // 2
    return total

