def min_deletion_size(strs: list[str]) -> int:
    n, m = len(strs), len(strs[0])
    settled = [False] * max(0, n - 1)   # settled[i]: strs[i] < strs[i+1] already decided
    deletions = 0
    for col in range(m):
        # Would keeping this column violate an unsettled pair?
        violated = False
        for i in range(n - 1):
            if not settled[i] and strs[i][col] > strs[i + 1][col]:
                violated = True
                break
        if violated:
            deletions += 1
            continue
        # Keep the column and settle pairs that are now strictly ordered.
        for i in range(n - 1):
            if strs[i][col] < strs[i + 1][col]:
                settled[i] = True
    return deletions

def is_rectangle_cover(rectangles: list[list[int]]) -> bool:
    corners = set()
    area = 0
    min_x = min_y = float("inf")
    max_x = max_y = float("-inf")
    for x1, y1, x2, y2 in rectangles:
        area += (x2 - x1) * (y2 - y1)
        min_x, min_y = min(min_x, x1), min(min_y, y1)
        max_x, max_y = max(max_x, x2), max(max_y, y2)
        for point in ((x1, y1), (x1, y2), (x2, y1), (x2, y2)):
            if point in corners:
                corners.remove(point)   # seen an even number of times
            else:
                corners.add(point)
    expected = {(min_x, min_y), (min_x, max_y), (max_x, min_y), (max_x, max_y)}
    if corners != expected:
        return False
    return area == (max_x - min_x) * (max_y - min_y)

