class Fancy:
    MOD = 10 ** 9 + 7

    def __init__(self):
        self.stored = []     # raw values; real value = mul * raw + add
        self.mul = 1
        self.add = 0
        self.inv = 1         # cached inverse of mul, or None when stale

    def append(self, val: int) -> None:
        if self.inv is None:
            self.inv = pow(self.mul, self.MOD - 2, self.MOD)
        raw = (val - self.add) * self.inv % self.MOD
        self.stored.append(raw)

    def addAll(self, inc: int) -> None:
        self.add = (self.add + inc) % self.MOD

    def multAll(self, m: int) -> None:
        self.mul = self.mul * m % self.MOD
        self.add = self.add * m % self.MOD
        self.inv = None      # recompute lazily on the next append

    def getIndex(self, idx: int) -> int:
        if idx >= len(self.stored):
            return -1
        return (self.stored[idx] * self.mul + self.add) % self.MOD

