def min_mirror_pair_distance(nums: list[int]) -> int:
    latest = {}        # reversed value -> most recent index producing it
    best = -1
    for j, value in enumerate(nums):
        i = latest.get(value)
        if i is not None and (best == -1 or j - i < best):
