def maximum_rows(matrix: list[list[int]], num_select: int) -> int:
    n = len(matrix[0])
    rows = []
    for row in matrix:
        mask = 0
        for j, bit in enumerate(row):
            if bit:
                mask |= 1 << j
        rows.append(mask)

    best = 0
    for chosen in range(1 << n):
        if bin(chosen).count("1") != num_select:
            continue
        covered = sum(1 for r in rows if r & ~chosen == 0)
        best = max(best, covered)
    return best

