def min_speed_on_time(dist: list[int], hour: float) -> int:
    n = len(dist)
    budget = round(hour * 100)       # hour in hundredths, exact
    if budget <= (n - 1) * 100:      # the waits alone take n - 1 full hours
        return -1

    def fits(speed: int) -> bool:
        hours = 0
        for d in dist[:-1]:
            hours += (d + speed - 1) // speed
        # hours + dist[-1] / speed <= budget / 100
        return (hours * speed + dist[-1]) * 100 <= budget * speed

    lo, hi = 1, 10 ** 7
    if not fits(hi):
        return -1
    while lo < hi:
        mid = (lo + hi) // 2
        if fits(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

