def json_stringify(obj: Any) -> str:
    parts = []

    def emit(value: Any) -> None:
        if value is None:
            parts.append("null")
        elif value is True:
            parts.append("true")
        elif value is False:
            parts.append("false")
        elif isinstance(value, str):
            parts.append('"' + value + '"')
        elif isinstance(value, (int, float)):
            parts.append(str(value))
        elif isinstance(value, list):
            parts.append("[")
            for i, item in enumerate(value):
                if i:
                    parts.append(",")
                emit(item)
            parts.append("]")
        else:   # dict, keys in insertion order
            parts.append("{")
            for i, (key, item) in enumerate(value.items()):
                if i:
                    parts.append(",")
                parts.append('"' + str(key) + '":')
                emit(item)
            parts.append("}")

    emit(obj)
    return "".join(parts)

