def maximum_invitations(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    partner = [-1] * n          # girl -> boy currently matched with her

    def try_match(boy: int, seen: list[bool]) -> bool:
        for girl in range(n):
            if grid[boy][girl] and not seen[girl]:
                seen[girl] = True
                if partner[girl] == -1 or try_match(partner[girl], seen):
                    partner[girl] = boy
                    return True
        return False

    matched = 0
    for boy in range(m):
        if try_match(boy, [False] * n):
            matched += 1
    return matched

def shifting_letters(s: str, shifts: list[int]) -> str:
    result = [""] * len(s)
    total = 0   # suffix sum of shifts, modulo 26
    for i in range(len(s) - 1, -1, -1):
        total = (total + shifts[i]) % 26
        result[i] = chr((ord(s[i]) - 97 + total) % 26 + 97)
    return "".join(result)
